import {escapeHtml as esc} from './components.js';
export const indicatorNames={sma:'SMA 단순이동평균',ema:'EMA 지수이동평균',bb:'볼린저밴드',volume:'거래량',rsi:'RSI 상대강도',macd:'MACD',ichimoku:'일목균형표 Ichimoku',stochastic:'스토캐스틱 Stochastic',atr:'ATR 평균진폭',obv:'OBV 누적거래량'};
export const drawingNames={horizontal:'수평선',trend:'추세선',range:'사각형'};
const num=(label,key,value,min=1,max=500,step=1)=>`<label>${label}<input type="number" required data-config="${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
export function indicatorFields(c){
 const lines=c.kind==='bb'?['중심선','상단선','하단선']:c.kind==='macd'?['MACD선','시그널선','히스토그램']:c.kind==='ichimoku'?['전환선','기준선','선행스팬 A','선행스팬 B','후행스팬']:c.kind==='stochastic'?['%K','%D']:['선'];
 return `<div class="sc-config-fields">${['sma','ema','bb','rsi','stochastic','atr'].includes(c.kind)?num('기간 (봉)','period',c.period):''}${c.kind==='bb'?num('표준편차 배수','deviations',c.deviations,.1,5,.1):''}${c.kind==='ichimoku'?num('전환선 (봉)','conversion',c.conversion)+num('기준선 (봉)','base',c.base)+num('선행 B (봉)','span',c.span)+num('이동 (봉)','displacement',c.displacement,1,100)+`<label class="sc-cloud-toggle"><input type="checkbox" data-config="cloud" ${c.cloud?'checked':''}>구름대 표시</label>`+num('구름대 불투명도 %','cloudOpacity',c.cloudOpacity,0,60):''}${c.kind==='stochastic'?num('%K 평활','smoothK',c.smoothK)+num('%D 평활','smoothD',c.smoothD):''}${c.kind==='macd'?num('빠른 EMA','fast',c.fast,2,499)+num('느린 EMA','slow',c.slow,3,500)+num('시그널','signal',c.signal,1,200):''}${c.kind!=='volume'?lines.map((label,i)=>`<label>${label} 색<input type="color" aria-label="${indicatorNames[c.kind]} ${label} 색상" data-color="${i}" value="${c.colors[i]}"></label>${num(label+' 두께','width-'+i,c.widths[i],.5,5,.1)}`).join(''):''}</div>${c.kind==='ichimoku'?'<p class="sc-note">봉 수만큼 선행스팬은 앞에, 후행스팬은 뒤에 표시합니다. 선행 구간은 계산값이며 미래 가격이 아닙니다. 구름 색은 선행스팬 A/B 색을 따릅니다.</p>':c.kind==='obv'?'<p class="sc-note">확보한 첫 봉을 0으로 시작한 누적값입니다. 거래량 누락 뒤는 표시하지 않습니다.</p>':c.kind==='atr'?'<p class="sc-note">Wilder 평활 · 가격과 같은 통화 단위</p>':''}`;
}
export function indicatorMenu(settings,{ohlc=true,volume=true}={}){
 return `<div class="sc-menu-heading"><strong>지표</strong><button data-menu-close aria-label="지표 메뉴 닫기">닫기</button></div><input class="sc-indicator-search" type="search" placeholder="지표 검색 · SMA, EMA, RSI…" aria-label="지표 검색"><div class="sc-catalog">${Object.entries(indicatorNames).map(([kind,name])=>`<div data-catalog="${kind}" data-keywords="${name.toLowerCase()}"><span>${name}</span><div>${(kind==='sma'?[5,20,60,120,200]:kind==='ema'?[12,26]:[null]).map(period=>`<button data-add-indicator="${kind}" ${(!ohlc&&['ichimoku','stochastic','atr'].includes(kind)||!volume&&['volume','obv'].includes(kind))?'disabled title="필요한 고가·저가 또는 거래량 자료가 없습니다"':''} ${period?'data-preset="'+period+'"':''}>+ ${period||'추가'}</button>`).join('')}</div></div>`).join('')}</div><div class="sc-indicator-list">${settings.indicators.map(c=>{

 return `<fieldset data-indicator-id="${c.id}"><legend><label><input type="checkbox" data-config="enabled" ${c.enabled?'checked':''}>${indicatorNames[c.kind]}</label><button data-remove-indicator="${c.id}" aria-label="${indicatorNames[c.kind]} 삭제">삭제</button></legend>${indicatorFields(c)}</fieldset>`;
 }).join('')||'<p>켜진 지표가 없습니다.</p>'}</div><p class="sc-note">기간은 선택한 봉 간격 기준입니다. 예: 주봉 SMA 20 = 20주 · 볼린저밴드: 모집단 표준편차 · RSI: Wilder 방식 · EMA: 최초 구간 SMA로 시작</p>`;
}
export function drawingMenu(drawings,selected,tool,canUndo){
 const drawing=drawings.find(d=>d.id===selected);
 return `<div class="sc-menu-heading"><strong>그리기</strong><button data-menu-close aria-label="그리기 메뉴 닫기">닫기</button></div><div class="sc-draw-tools"><button data-tool="select" aria-pressed="${tool==='select'}">선택 / 이동</button>${Object.entries(drawingNames).map(([kind,name])=>`<button data-tool="${kind}" aria-pressed="${tool===kind}">${name}</button>`).join('')}<button data-undo ${canUndo?'':'disabled'}>실행 취소</button></div><p class="sc-note">수평선은 한 점, 추세선·구간은 두 점을 누르세요. 객체나 끝점을 드래그해 수정할 수 있습니다.</p><div class="sc-drawing-list">${drawings.map((d,i)=>`<button data-select-drawing="${d.id}" aria-pressed="${selected===d.id}">${drawingNames[d.kind]} ${i+1}</button>`).join('')}</div>${drawing?`<form class="sc-drawing-form" data-edit-drawing="${drawing.id}"><strong>선택한 ${drawingNames[drawing.kind]} 수정</strong><div class="sc-config-fields">${drawing.points.map((p,i)=>`<label>${i+1}번 날짜<input type="date" name="date${i}" required value="${p.date}"></label><label>${i+1}번 가격<input type="number" name="price${i}" required min="0" step="any" value="${p.price}"></label>`).join('')}<label>색상<input type="color" name="color" value="${drawing.color}"></label><label>두께<input type="number" name="width" min=".5" max="5" step=".5" value="${drawing.width}"></label></div><div class="sc-draw-tools"><button type="submit">수정 적용</button><button type="button" data-delete-drawing="${drawing.id}">선택 객체 삭제</button></div></form>`:''}`;
}
export function settingsMenu(settings,scale){
 return `<div class="sc-menu-heading"><strong>차트 설정</strong><button data-menu-close aria-label="설정 메뉴 닫기">닫기</button></div><div class="sc-settings-checks"><label><input type="checkbox" data-setting="grid" ${settings.grid?'checked':''}>격자 표시</label><label><input type="checkbox" data-setting="currentPrice" ${settings.currentPrice?'checked':''}>제공 현재가 수평선</label><label>가격 축 배율<input type="range" data-price-scale min="0.25" max="4" step=".05" value="${scale}" aria-label="가격 축 범위"></label></div><div class="sc-draw-tools"><button data-save-default>기본 차트 설정으로 저장</button><button data-reset-settings>설정 초기화</button><button data-clear-drawings>이 종목의 그리기만 삭제</button></div><p class="sc-note">설정과 그리기는 이 브라우저에 종목별로 저장됩니다. 기본 설정은 아직 설정을 저장하지 않은 종목에 적용됩니다. 설정 초기화는 그리기를 지우지 않습니다.</p>`;
}
export function comparisonMenu(comparisons,{indices=true}={}){
 return `<div class="sc-menu-heading"><strong>종목 비교</strong><button data-menu-close aria-label="종목 비교 메뉴 닫기">닫기</button></div><input type="search" class="sc-compare-search" aria-label="${indices?'비교할 종목 또는 지수 검색':'비교할 종목 검색'}" placeholder="${indices?'종목명·티커·지수 검색':'종목명·티커 검색'}"><div class="sc-compare-results" role="status"></div><div class="sc-comparisons">${comparisons.map(c=>`<div><label><input type="color" data-compare-color="${esc(c.key)}" value="${c.color}" aria-label="${esc(c.label)} 비교 색상">${esc(c.label)}</label><button data-remove-compare="${esc(c.key)}" aria-label="${esc(c.label)} 비교 삭제">삭제</button></div>`).join('')}</div><p class="sc-note">최대 3개 · 아래 수익률 패널에서 같은 실제 시작일을 0%로 비교합니다. 가격 이력이 없는 날짜는 연결하지 않습니다. 차트 권한과 일봉이 확인되는 대상만 추가됩니다.</p>`;
}
